fn perfect_numbers_up_to(n: Int) -> Vec<Int> {
    (range(2, n)
        .filter(|x| sum_of_divisors(x) == x)
        .collect())
}

fn sum_of_divisors(x: Int) -> Int {
    (range(1, x)
        .filter(|&d| x % d == 0)
        .fold(0, |acc, d| acc + d))
}

fn main() {
    print(perfect_numbers_up_to(1000))
}

struct Point { x: Float, y: Float }

fn dist(a: Point, b: Point) -> Float {
    ((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y)).sqrt()
}

fn main() {
    let p1 = Point { x: 3.0, y: 4.0 }
    let p2 = Point { x: 0.0, y: 0.0 }
    print(dist(p1, p2))
}

fn perfect_nums(n: Int) -> Vec<Int> {
    if n == 0 {
        return vec();
    } else {
        let divisors = filter(|d| d < n && n % d == 0, range(1, n));
        let sum = reduce(|acc, d| acc + d, divisors, 0);
        if sum == n {
            return push(vec(), n);
        } else {
            return perfect_nums(n + 1);
        }
    }
}

fn main() {
    let perfects = perfect_nums(2);
    for p in perfects {
        print_str("Perfect number: ");
        print(p);
        print_str("\n");
    }
}

